action.command:
cat > /tmp/check.sh <<'EOF'
source /app/init.sh >/dev/null 2>&1 || true
ok=1
[ "$DEV_HOME" = "/workspace" ] && echo "DEV_HOME OK" || { echo "DEV_HOME FAIL=[$DEV_HOME]"; ok=0; }
[ "$PROJECT_ROOT" = "/workspace/project" ] && echo "PROJECT_ROOT OK" || { echo "PROJECT_ROOT FAIL"; ok=0; }
[ "$API_KEY" = "sk-test-12345-abcdef" ] && echo "API_KEY OK" || { echo "API_KEY FAIL=[$API_KEY]"; ok=0; }
[ "$DB_URL" = "postgres://user:pass@localhost:5432/devdb" ] && echo "DB_URL OK" || { echo "DB_URL FAIL"; ok=0; }
case ":$PATH:" in *:/workspace/tools/bin:*:/workspace/scripts:*) echo "PATH OK";; *) echo "PATH FAIL=[$PATH]"; ok=0;; esac
command -v devtool >/dev/null && echo "devtool OK" || { echo "devtool MISSING"; ok=0; }
command -v buildhelper >/dev/null && echo "buildhelper OK" || { echo "buildhelper MISSING"; ok=0; }
[ $ok -eq 1 ] && echo "ALL PASS" || echo "SOME FAIL"
EOF
bash /tmp/check.sh

